    return NULL;
}

int main() {
    pthread_t thread;
    // Create a new thread
    pthread_create(&thread, NULL, threadFunc, NULL);
    pthread_join(thread, NULL);
    return 0;
}", "type": "code", "heading": "Threading Example"}, {"type": "code_practice", "context": "Use pthread_join to wait for the thread to finish, passing the thread ID and NULL for the return value.", "heading": "Join the Thread", "code_after": ");
    return 0;
}", "code_before": "#include <stdio.h>
